/**
 * Rule: semantics/button-name
 * Satisfies: wcag22:4.1.2, wcag21:4.1.2
 * Spec: https://www.w3.org/TR/WCAG22/#name-role-value
 *
 * > For all user interface components (including but not limited to:
 * > form elements, links and components generated by scripts), the
 * > name and role can be programmatically determined; […].
 *
 * Source: https://www.w3.org/TR/WCAG22/#name-role-value
 *
 * Flags `<button>` and `role="button"` elements with no accessible
 * name. A button's accessible name can come from:
 *   - visible text content (including SVG `<title>` / `<text>`
 *     descendants — SVG 2 accessibility chapter specifies these as
 *     accessible-name sources for the ancestor interactive control)
 *   - aria-label
 *   - aria-labelledby (pointer to another element's text)
 *   - title (last resort — not announced by every AT but counts)
 *   - for <input type="submit|button|reset">: the `value` attribute,
 *     or an implicit default string per HTML spec
 *   - for <input type="image">: `alt`, `aria-label`, `aria-labelledby`,
 *     or `title` (per HTML §4.10.5.1.18 image button labeling)
 *
 * A button with only an icon child and no label is the canonical
 * failure: screen readers announce "button" with no action.
 */

import { defineRule } from "../../api/plugin.ts";
import {
  findHtmlElementsByTag,
  findJsxElementsByTag,
  findJsxElementsForTag,
  getHtmlAttribute,
  getJsxAttribute,
  getJsxAttributeString,
  hasHtmlAttribute,
  hasJsxAttribute,
  htmlTextContent,
  jsxTextContent,
  truncateForEcho,
  walkHtmlElements,
  walkJsxElements,
} from "../../engine/ast-helpers.ts";
import {
  htmlSubtreeHasStrippedDirective,
  TEMPLATE_DIRECTIVE_STRIPPED_SUFFIX,
} from "../../input/parsers/html-template-directives.ts";
import type { HtmlDocument, HtmlElement, JsxElement, TsxModule } from "../../types/ast.ts";
import type { FixPaths } from "../../types/violation.ts";
import { matchFaGlyph } from "./_fa-glyph-labels.ts";
import { buildAttributeInsertEdit } from "./_open-tag-attr-edit.ts";

export const rule = defineRule({
  id: "semantics/button-name",
  satisfies: ["wcag22:4.1.2", "wcag21:4.1.2"],
  severity: "error",
  scope: "node",
  fixClass: "verify-in-source",
  // Opt in: wrapper components declared as rendering `<button>` via the
  // object form of `nativeWrappers`, plus polymorphic `<Wrapper as="button">`
  // / `<Slot asChild><button>…</button></Slot>` call sites.
  // All three channels get the same icon-only / empty-button accessible-name
  // check as a bare `<button>`.
  wrapperTreatsAsElement: "button",
  appliesTo: {
    fileExtensions: [".html", ".htm", ".tsx", ".jsx"],
  },
  docs: {
    description:
      "Every button must have an accessible name — via visible text (including SVG <title>/<text> descendants), aria-label, aria-labelledby, title, or for input type=submit/button the value attribute. For input type=image, alt / aria-label / aria-labelledby / title are the valid name sources (value is not).",
    rationale:
      "Screen readers announce a button by its accessible name. A button with only an icon child and no label is announced as 'button' — the user has no idea what it does. Icon-only buttons are one of the top-3 accessibility failures in audits.",
    goodExample: `<button aria-label="Close dialog"><svg>...</svg></button>`,
    badExample: `<button><svg>...</svg></button>`,
    normativeQuote:
      "For all user interface components the name and role can be programmatically determined.",
    references: [
      "https://www.w3.org/TR/WCAG22/#name-role-value",
      "https://www.w3.org/WAI/ARIA/apg/practices/names-and-descriptions/",
    ],
  },
  check(ctx) {
    if (ctx.language === "html") {
      checkHtml(ctx.ast as HtmlDocument, ctx.source, (v) => ctx.emit(v));
    } else if (
      ctx.language === "tsx" ||
      ctx.language === "jsx" ||
      ctx.language === "ts" ||
      ctx.language === "js"
    ) {
      checkJsx(ctx.ast as TsxModule, ctx.source, ctx.wrappersForElement, (v) => ctx.emit(v));
    }
  },
});

type Emit = (v: {
  severity: "error" | "warning" | "info";
  location: { filePath: string; line: number; column: number };
  message: string;
  suggestion: string;
  fixPaths?: FixPaths;
}) => void;

// ---------------------------------------------------------------------------
// HTML
// ---------------------------------------------------------------------------

function checkHtml(doc: HtmlDocument, source: string, emit: Emit): void {
  checkHtmlNativeButtons(doc, source, emit);
  checkHtmlInputButtons(doc, emit);
  checkHtmlRoleButtons(doc, source, emit);
}

function checkHtmlNativeButtons(doc: HtmlDocument, source: string, emit: Emit): void {
  for (const button of findHtmlElementsByTag(doc, "button")) {
    if (hasAccessibleNameHtml(button)) continue;
    // Per docs/kb/architecture/ai-first-consumer.md §"Surface, don't
    // suppress": `<button>{{ t.submit }}</button>` has its only child
    // stripped by the parser, so the accessible-name check fails with
    // no static evidence of a name. Finding still emits at `error`;
    // the reason text carries the template_directive_stripped signal.
    const icon = describeIconChildHtml(button);
    emit(
      buildViolation(
        "button",
        button.loc.start,
        icon,
        htmlSubtreeHasStrippedDirective(button),
        buildFaIconFixPathsHtml(button, source, icon),
      ),
    );
  }
}

function checkHtmlInputButtons(doc: HtmlDocument, emit: Emit): void {
  for (const input of findHtmlElementsByTag(doc, "input")) {
    if (!isButtonInputHtml(input)) continue;
    if (hasInputButtonNameHtml(input)) continue;
    const type = (getHtmlAttribute(input, "type") ?? "").toLowerCase();
    const iconCtx =
      type === "image" ? describeImageInputHtml(input) : ({ kind: "empty" } satisfies IconContext);
    // <input> is void — no element children, so no template-stripped
    // signal to propagate. A value="{{ t.submit }}" interpolation is
    // already handled: attribute values aren't subject to the parser's
    // text-node stripping and surface unchanged.
    emit(buildViolation(`input type="${type}"`, input.loc.start, iconCtx, false, undefined));
  }
}

function checkHtmlRoleButtons(doc: HtmlDocument, source: string, emit: Emit): void {
  for (const el of walkHtmlElements(doc)) {
    const lowered = el.tagName.toLowerCase();
    if (lowered === "button" || lowered === "input") continue;
    if (getHtmlAttribute(el, "role")?.toLowerCase() !== "button") continue;
    if (hasAccessibleNameHtml(el)) continue;
    const icon = describeIconChildHtml(el);
    emit(
      buildViolation(
        `${el.tagName} role="button"`,
        el.loc.start,
        icon,
        htmlSubtreeHasStrippedDirective(el),
        buildFaIconFixPathsHtml(el, source, icon),
      ),
    );
  }
}

function hasAccessibleNameHtml(element: HtmlElement): boolean {
  // `htmlTextContent` walks every descendant HtmlText — which already
  // covers SVG `<title>` (raw-text element) and `<text>` children
  // nested under an interactive control. Kept as the primary check so
  // authors using `<button><svg><title>Close</title></svg></button>`
  // pass cleanly. The explicit `hasSvgNameDescendantHtml` below is a
  // belt-and-braces guard in case parser treatment of raw-text
  // elements changes: it walks SVG descendants and returns true for a
  // non-empty `<title>` / `<text>` even if `htmlTextContent` ever
  // stopped surfacing it.
  if (htmlTextContent(element).length > 0) return true;
  if (hasSvgNameDescendantHtml(element)) return true;
  if (hasHtmlAriaName(element)) return true;
  if (hasHtmlChildImgAlt(element)) return true;
  return false;
}

/**
 * True when the element has an SVG `<title>` or `<text>` descendant
 * with non-empty text. SVG 2 accessibility chapter treats these as
 * accessible-name sources for the ancestor interactive control
 * (button, link, role="button").
 */
function hasSvgNameDescendantHtml(element: HtmlElement): boolean {
  for (const child of element.children) {
    if (child.kind !== "HtmlElement") continue;
    const tag = child.tagName.toLowerCase();
    if ((tag === "title" || tag === "text") && htmlTextContent(child).length > 0) return true;
    if (hasSvgNameDescendantHtml(child)) return true;
  }
  return false;
}

function hasHtmlAriaName(element: HtmlElement): boolean {
  const ariaLabel = getHtmlAttribute(element, "aria-label");
  if (ariaLabel !== null && ariaLabel.trim().length > 0) return true;
  if (hasHtmlAttribute(element, "aria-labelledby")) return true;
  const title = getHtmlAttribute(element, "title");
  if (title !== null && title.trim().length > 0) return true;
  return false;
}

function hasHtmlChildImgAlt(element: HtmlElement): boolean {
  for (const child of element.children) {
    if (child.kind !== "HtmlElement") continue;
    if (child.tagName.toLowerCase() !== "img") continue;
    const alt = getHtmlAttribute(child, "alt");
    if (alt !== null && alt.trim().length > 0) return true;
  }
  return false;
}

function isButtonInputHtml(element: HtmlElement): boolean {
  const type = (getHtmlAttribute(element, "type") ?? "").toLowerCase();
  return type === "button" || type === "submit" || type === "reset" || type === "image";
}

function hasInputButtonNameHtml(element: HtmlElement): boolean {
  const type = (getHtmlAttribute(element, "type") ?? "").toLowerCase();
  // `<input type="image">` is named via `alt` / aria-* / `title` per
  // HTML §4.10.5.1.18. `value` is not a name source for image buttons
  // (it submits as form data), and there is no UA-default fallback.
  if (type === "image") return hasImageInputNameHtml(element);
  const value = getHtmlAttribute(element, "value");
  if (value !== null && value.trim().length > 0) return true;
  if (hasHtmlAriaName(element)) return true;
  // type=submit and type=reset have a UA-default label ("Submit" / "Reset").
  // The spec considers that a valid accessible name even though it's locale-
  // dependent and unhelpful.
  if (type === "submit" || type === "reset") return true;
  return false;
}

function hasImageInputNameHtml(element: HtmlElement): boolean {
  const alt = getHtmlAttribute(element, "alt");
  if (alt !== null && alt.trim().length > 0) return true;
  return hasHtmlAriaName(element);
}

// ---------------------------------------------------------------------------
// JSX
// ---------------------------------------------------------------------------

function checkJsx(
  module: TsxModule,
  source: string,
  wrappersForButton: ReadonlySet<string>,
  emit: Emit,
): void {
  checkJsxNativeButtons(module, source, wrappersForButton, emit);
  checkJsxInputButtons(module, emit);
  checkJsxRoleButtons(module, source, emit);
}

function checkJsxNativeButtons(
  module: TsxModule,
  source: string,
  wrappersForButton: ReadonlySet<string>,
  emit: Emit,
): void {
  // Three resolution channels: bare `<button>`, mapped wrappers
  // (`{ IconButton: "button" }`), and polymorphic `as="button"` /
  // `asChild` → `<button>`. The accessible-name
  // rules apply uniformly — the call-site attrs/children on a wrapper
  // are what forward to the inner `<button>`.
  const seen = new Set<JsxElement>();
  for (const button of findJsxElementsForTag(module, "button", wrappersForButton)) {
    if (seen.has(button)) continue;
    seen.add(button);
    if (hasAccessibleNameJsx(button)) continue;
    emit(buildJsxViolation("button", button, describeIconChildJsx(button), source));
  }
}

function checkJsxInputButtons(module: TsxModule, emit: Emit): void {
  for (const input of findJsxElementsByTag(module, "input")) {
    if (!isButtonInputJsx(input)) continue;
    if (hasInputButtonNameJsx(input)) continue;
    const type = getJsxAttributeString(input, "type") ?? "";
    const iconCtx =
      type === "image" ? describeImageInputJsx(input) : ({ kind: "empty" } satisfies IconContext);
    emit(buildJsxViolation(`input type="${type}"`, input, iconCtx, undefined));
  }
}

function checkJsxRoleButtons(module: TsxModule, source: string, emit: Emit): void {
  for (const el of walkJsxElements(module)) {
    if (el.tagName === "button" || el.tagName === "input") continue;
    if (getJsxAttributeString(el, "role") !== "button") continue;
    if (hasAccessibleNameJsx(el)) continue;
    emit(buildJsxViolation(`${el.tagName} role="button"`, el, describeIconChildJsx(el), source));
  }
}

function buildJsxViolation(
  subject: string,
  el: JsxElement,
  icon: IconContext,
  source: string | undefined,
) {
  const loc = { filePath: "", line: el.loc.start.line, column: el.loc.start.column };
  if (el.hasSpreadProps) {
    return {
      severity: "info" as const,
      location: loc,
      message: `<${subject}> has no static accessible name but receives {...spread} props — this looks like a component primitive. Whether the button has a name at render time depends on what the caller passes (aria-label, visible text children). Verify at usage sites.`,
      suggestion: `If the primitive is only consumed by callers that pass a label via props or children, this is fine — add \`{/* ra11y-disable semantics/button-name */}\` at the top of the file to silence this info note. Otherwise require callers to pass a name.`,
    };
  }
  // when the button wraps a
  // known FA glyph and `source` is plumbed through, ship the
  // `fixPaths.primary.edit` matching the prose so `suggest_fix`
  // returns `kind: "edit"` instead of `kind: "guidance"`.
  const fixPaths = source === undefined ? undefined : buildFaIconFixPathsJsx(el, source, icon);
  return {
    severity: "error" as const,
    location: loc,
    message: `<${subject}> has no accessible name — screen readers will announce it as "button" with no action.`,
    suggestion: buildIconAwareSuggestion(subject, icon),
    ...(fixPaths === undefined ? {} : { fixPaths }),
  };
}

function hasAccessibleNameJsx(element: JsxElement): boolean {
  if (jsxTextContent(element).length > 0) return true;
  // SVG `<title>` / `<text>` descendant with literal text is an
  // accessible-name source (SVG 2 accessibility). Keep the check above
  // the broad content-children heuristic below so the specific match
  // wins — the two are compatible but the explicit path expresses
  // intent for code-review.
  if (hasSvgNameDescendantJsx(element)) return true;
  // Expression descendants like {label} likely produce text at runtime
  // — including when nested under a presentational wrapper (e.g.
  // `<button><span>{label}</span></button>`). Walk recursively so a
  // wrapper element doesn't hide the runtime-text signal. Flagging
  // `<button>{label}</button>` as "no name" would be a false positive.
  // (We deliberately do NOT short-circuit on bare JsxElement children:
  // before, any child element
  // — including a presentational `<i class="fa-…">` icon — silenced
  // the rule. Now the only structural signals that count as "likely
  // has a name" are literal text, a JSX expression descendant, an
  // SVG `<title>`/`<text>`, an `<img alt>`, or a PascalCase child.)
  if (hasJsxExpressionDescendant(element)) return true;
  if (hasJsxAriaName(element)) return true;
  if (hasJsxChildNameSource(element)) return true;
  return false;
}

/**
 * True when any descendant child node is a `JsxExpression` (`{label}`,
 * `{t('save')}`, etc.). Walks through `JsxElement` wrappers because the
 * expression often sits inside a styling span — `<button><span class=
 * "label">{label}</span></button>`. Used as the runtime-text signal for
 * accessible-name detection: literal text is caught by `jsxTextContent`,
 * runtime-text is caught here.
 */
function hasJsxExpressionDescendant(element: JsxElement): boolean {
  for (const child of element.children) {
    if (child.kind === "JsxExpression") return true;
    if (child.kind === "JsxElement" && hasJsxExpressionDescendant(child)) return true;
  }
  return false;
}

/**
 * True when the JSX element has an SVG `<title>` or `<text>`
 * descendant whose literal text content is non-empty. Matches the HTML
 * counterpart in `hasSvgNameDescendantHtml`.
 */
function hasSvgNameDescendantJsx(element: JsxElement): boolean {
  for (const child of element.children) {
    if (child.kind !== "JsxElement") continue;
    if (child.tagName === "title" || child.tagName === "text") {
      if (jsxTextContent(child).length > 0) return true;
    }
    if (hasSvgNameDescendantJsx(child)) return true;
  }
  return false;
}

function hasJsxAriaName(element: JsxElement): boolean {
  const ariaLabel = getJsxAttributeString(element, "aria-label");
  if (ariaLabel !== null && ariaLabel.trim().length > 0) return true;
  if (hasJsxAttribute(element, "aria-labelledby")) return true;
  const title = getJsxAttributeString(element, "title");
  if (title !== null && title.trim().length > 0) return true;
  // aria-label as a runtime expression is a false negative we accept.
  const ariaAttr = getJsxAttribute(element, "aria-label");
  if (ariaAttr?.value?.kind === "Expression") return true;
  return false;
}

function hasJsxChildNameSource(element: JsxElement): boolean {
  for (const child of element.children) {
    if (child.kind !== "JsxElement") continue;
    // Child <img alt="..."> is an accessible name source.
    if (child.tagName === "img") {
      const alt = getJsxAttributeString(child, "alt");
      if (alt !== null && alt.trim().length > 0) return true;
    }
    // PascalCase component children (e.g., <Icon label="..."/>) likely
    // supply their own name internally. Accepting false-negatives beats
    // spamming warnings on every component-wrapped button.
    if (isPascalCase(child.tagName)) return true;
  }
  return false;
}

function isPascalCase(tag: string): boolean {
  return tag.length > 0 && tag[0] !== undefined && tag[0] >= "A" && tag[0] <= "Z";
}

function isButtonInputJsx(element: JsxElement): boolean {
  const type = getJsxAttributeString(element, "type");
  return type === "button" || type === "submit" || type === "reset" || type === "image";
}

function hasInputButtonNameJsx(element: JsxElement): boolean {
  const type = getJsxAttributeString(element, "type");
  // `<input type="image">`: `alt` / aria-* / `title` only; no UA default.
  if (type === "image") return hasImageInputNameJsx(element);
  const value = getJsxAttributeString(element, "value");
  if (value !== null && value.trim().length > 0) return true;
  if (hasJsxAriaName(element)) return true;
  // Runtime-valued value={x} — can't statically verify; assume OK.
  const valueAttr = getJsxAttribute(element, "value");
  if (valueAttr?.value?.kind === "Expression") return true;
  if (type === "submit" || type === "reset") return true;
  return false;
}

function hasImageInputNameJsx(element: JsxElement): boolean {
  const alt = getJsxAttributeString(element, "alt");
  if (alt !== null && alt.trim().length > 0) return true;
  const altAttr = getJsxAttribute(element, "alt");
  if (altAttr?.value?.kind === "Expression") return true;
  return hasJsxAriaName(element);
}

function buildViolation(
  subject: string,
  loc: { line: number; column: number },
  icon: IconContext,
  templateStripped: boolean,
  fixPaths: FixPaths | undefined,
): {
  severity: "error";
  location: { filePath: string; line: number; column: number };
  message: string;
  suggestion: string;
  fixPaths?: FixPaths;
} {
  const base = `<${subject}> has no accessible name — screen readers will announce it as "button" with no action.`;
  return {
    severity: "error",
    location: { filePath: "", line: loc.line, column: loc.column },
    message: templateStripped ? `${base}${TEMPLATE_DIRECTIVE_STRIPPED_SUFFIX}` : base,
    suggestion: buildIconAwareSuggestion(subject, icon),
    ...(fixPaths === undefined ? {} : { fixPaths }),
  };
}

// ---------------------------------------------------------------------------
// Icon-child inspection for context-aware fix suggestions.
// ---------------------------------------------------------------------------

/**
 * What the unnamed button/role=button is currently wrapping — if
 * anything. Drives the fix text so the agent gets a concrete
 * aria-label candidate rather than a generic "add a name".
 *
 * `fa-icon` fires only when the only interesting child is an `<i>`
 * whose class attribute carries a glyph token in the shared
 * `FA_GLYPH_LABELS` map (see `_fa-glyph-labels.ts`). Unknown glyphs
 * (e.g. `fa-flux-capacitor`) fall through to `empty` so the existing
 * generic fix stays primary — we only emit a glyph-derived
 * aria-label when the map speaks for the glyph.
 */
type IconContext =
  | { kind: "svg-no-title" }
  | { kind: "img"; subject: string | null }
  | { kind: "fa-icon"; label: string; glyph: string }
  | { kind: "empty" };

function describeIconChildHtml(element: HtmlElement): IconContext {
  // The caller has already confirmed no accessible name — so
  // htmlTextContent is empty, no SVG <title>/<text> descendant has
  // text, and no child <img alt="…"> exists. We just need to know
  // whether the icon shell is an <svg>, <img>, <i class="fa-…">, or
  // nothing. Per-child classification is split into `classifyIconChildHtml`
  // to keep this loop under Biome's cognitive-complexity ceiling.
  for (const child of element.children) {
    if (child.kind !== "HtmlElement") continue;
    const ctx = classifyIconChildHtml(child);
    if (ctx !== null) return ctx;
  }
  return { kind: "empty" };
}

function classifyIconChildHtml(child: HtmlElement): IconContext | null {
  const tag = child.tagName.toLowerCase();
  if (tag === "svg") return { kind: "svg-no-title" };
  if (tag === "img") {
    const src = getHtmlAttribute(child, "src");
    return { kind: "img", subject: src ? subjectFromSrc(src) : null };
  }
  if (tag === "i" || tag === "span") {
    const cls = getHtmlAttribute(child, "class");
    if (cls === null) return null;
    const hit = matchFaGlyph(cls);
    if (hit !== null) return { kind: "fa-icon", label: hit.label, glyph: hit.glyph };
  }
  return null;
}

function describeIconChildJsx(element: JsxElement): IconContext {
  for (const child of element.children) {
    if (child.kind !== "JsxElement") continue;
    const ctx = classifyIconChildJsx(child);
    if (ctx !== null) return ctx;
  }
  return { kind: "empty" };
}

function classifyIconChildJsx(child: JsxElement): IconContext | null {
  if (child.tagName === "svg") return { kind: "svg-no-title" };
  if (child.tagName === "img") {
    const src = getJsxAttributeString(child, "src");
    return { kind: "img", subject: src ? subjectFromSrc(src) : null };
  }
  if (child.tagName === "i" || child.tagName === "span") {
    const cls = getJsxAttributeString(child, "className") ?? getJsxAttributeString(child, "class");
    if (cls === null) return null;
    const hit = matchFaGlyph(cls);
    if (hit !== null) return { kind: "fa-icon", label: hit.label, glyph: hit.glyph };
  }
  return null;
}

function describeImageInputHtml(input: HtmlElement): IconContext {
  const src = getHtmlAttribute(input, "src");
  return { kind: "img", subject: src ? subjectFromSrc(src) : null };
}

function describeImageInputJsx(input: JsxElement): IconContext {
  const src = getJsxAttributeString(input, "src");
  return { kind: "img", subject: src ? subjectFromSrc(src) : null };
}

/**
 * Derive a Title-Cased action-verb candidate from an image src. The
 * source filename is the strongest static signal we have for what
 * the icon is ("close.svg" → "Close", "icons/trash-bin.png" →
 * "Trash Bin"). Mirrors the `guessSubject` helper in
 * `media/alt-text-missing` (rules are pure — kept local to preserve
 * CLAUDE.md §3 invariant 6's no-cross-rule-imports rule).
 */
function subjectFromSrc(src: string): string | null {
  const slash = Math.max(src.lastIndexOf("/"), src.lastIndexOf("\\"));
  const filename = slash === -1 ? src : src.slice(slash + 1);
  const words = filename
    .replace(/\.[a-zA-Z0-9]+$/, "")
    .replace(/[-_]+/g, " ")
    .trim();
  if (words.length === 0) return null;
  return words
    .split(/\s+/)
    .map((w) => (w.length > 0 ? (w[0]?.toUpperCase() ?? "") + w.slice(1) : w))
    .join(" ");
}

/**
 * Build a context-aware suggestion that references the actual icon
 * shell the button is wrapping. Four branches:
 *
 *   - `svg-no-title`: inline the two fixes — add `<title>` inside the
 *     SVG (counts as accessible name via SVG 2) *or* `aria-label` on
 *     the button. Names a concrete example verb to anchor the edit.
 *   - `img` with derived subject: inline the filename-derived subject
 *     as the aria-label / alt candidate.
 *   - `fa-icon`: the only interesting child is an `<i>` / `<span>`
 *     whose class carries a known Font Awesome glyph token. The
 *     glyph→label map speaks for the glyph, so emit
 *     `aria-label="<label>"` as the primary fix and keep "add visible
 *     text" as the secondary. Unknown glyphs do not reach this branch
 *     — they fall through to `empty` so the generic fix stays primary.
 *   - `img` without subject / `empty`: fall back to naming concrete
 *     action-verb examples (Close, Submit, Save, Delete) rather than
 *     the generic "add a name" placeholder the audit flagged.
 */
function buildIconAwareSuggestion(subject: string, icon: IconContext): string {
  const host = `<${subject}>`;
  const isImageInput = subject === 'input type="image"';
  if (icon.kind === "svg-no-title") {
    return `${host} wraps an <svg> with no <title>/<text> descendant. Two fixes: (1) add a <title> child inside the <svg> — e.g., <svg><title>Close</title>…</svg> — which counts toward the accessible name on the interactive ancestor (SVG 2 accessibility); or (2) add aria-label="Close" on the ${host}. Replace "Close" with the button's action verb (Submit, Save, Delete, etc.).`;
  }
  if (icon.kind === "fa-icon") {
    // Primary: glyph-derived aria-label (the map speaks for the glyph).
    // Secondary: visible text. The rule still fires — only the fix
    // text changes. Verify the label against the button's actual
    // action: the filename-hint caveat applies here too (the glyph is
    // a strong hint, not a guarantee).
    return `${host} wraps an <i class="${icon.glyph}"> icon-font glyph with no accessible name. Primary fix: aria-label="${icon.label}" on the ${host} — derived from the Font Awesome glyph name. Secondary: add visible text — e.g., <${subject}>${icon.label}</${subject}>. Also add aria-hidden="true" on the inner <i> so AT doesn't double-announce the icon alongside the label. Verify "${icon.label}" matches the button's actual action — the glyph is a hint, not a guarantee.`;
  }
  if (icon.kind === "img") {
    // `subjectHint` is derived from a user-authored `src` filename and
    // echoed twice per suggestion — a long filename path would otherwise
    // double the echo cost. Cap before interpolation.
    const subjectHint = icon.subject === null ? null : truncateForEcho(icon.subject);
    if (isImageInput) {
      // The image button IS the image — name alt on itself, not on a child.
      if (subjectHint !== null) {
        return `${host} has no accessible name. Set alt="${subjectHint}" on the input (derived from the src filename), or aria-label="${subjectHint}". Per HTML §4.10.5.1.18, value is not a name source for image buttons — only alt, aria-label, aria-labelledby, or title count. Verify the derived subject matches the button's actual action.`;
      }
      return `${host} has no accessible name. Add alt="<action>" on the input, or aria-label="<action>", where <action> is the button's verb (Close, Submit, Save, Delete). Per HTML §4.10.5.1.18, value is not a name source for image buttons.`;
    }
    if (subjectHint !== null) {
      return `${host} wraps an <img> with no alt text. Set alt="${subjectHint}" on the <img> (derived from the src filename), or aria-label="${subjectHint}" on the ${host}. Verify the derived subject matches the button's actual action — the filename is a hint, not a guarantee.`;
    }
    return `${host} wraps an <img> with no alt text and no src to infer from. Add alt="<action>" on the <img>, or aria-label="<action>" on the ${host}, where <action> is the button's verb (Close, Submit, Save, Delete).`;
  }
  if (isImageInput) {
    return `${host} has no accessible name and no src to infer from. Add alt="<action>" or aria-label="<action>", where <action> is the button's verb (Close, Submit, Save, Delete). Per HTML §4.10.5.1.18, value is not a name source for image buttons.`;
  }
  if (subject.startsWith("input ")) {
    return `${host} has no accessible name. Set value="Close" (or the button's action verb — Submit, Save, Delete), or add aria-label="Close". For input type="submit"/"reset" a non-empty value is the canonical name source.`;
  }
  return `${host} is empty. Add visible text — e.g., <${subject}>Close</${subject}> — or aria-label="Close" for icon-only variants. Replace "Close" with the button's action verb (Submit, Save, Delete, etc.), and use aria-labelledby="<id>" when the label already exists as visible text elsewhere in the DOM.`;
}

// ---------------------------------------------------------------------------
// FA-icon mechanical edit (
//).
//
// When the unnamed `<button>` / `role="button"` element wraps an
// `<i class="(fa|fas|far|fab) fa-<glyph>">` whose glyph is in the
// shared `FA_GLYPH_LABELS` map (see `_fa-glyph-labels.ts`), we ship a
// deterministic `fixPaths.primary.edit` that inserts
// ` aria-label="<derived>"` into the host's open tag — so `suggest_fix`
// returns `kind: "edit"` and matches the prose ("Primary fix:
// aria-label=\"Close\"") rather than `kind: "guidance"`.
//
// Both the FA-glyph derivation and the open-tag boundary scanner are
// extracted (`_fa-glyph-labels.ts`, `_open-tag-attr-edit.ts`) so a
// single derivation drives every surface — fixDescription prose,
// rule-emitted `fixPaths.primary.edit`, and the `suggest_fix` outcome
// shape that consumes them.
// ---------------------------------------------------------------------------

function buildFaIconFixPathsHtml(
  element: HtmlElement,
  source: string,
  icon: IconContext,
): FixPaths | undefined {
  if (icon.kind !== "fa-icon") return undefined;
  const tag = element.tagName.toLowerCase();
  const edit = buildAttributeInsertEdit(element.range.start, element.range.end, source, {
    tagName: tag,
    attrName: "aria-label",
    attrValue: icon.label,
    dialect: "html",
  });
  if (edit === null) return undefined;
  return {
    primary: {
      label: `add aria-label="${icon.label}" to <${tag}>`,
      edit,
    },
    alternatives: [],
  };
}

function buildFaIconFixPathsJsx(
  element: JsxElement,
  source: string,
  icon: IconContext,
): FixPaths | undefined {
  if (icon.kind !== "fa-icon") return undefined;
  // JSX preserves the tagName casing the author wrote (e.g. `button`,
  // `Button`, `Slot`); the open-tag scanner matches the literal tag
  // name in source so case-as-authored is correct.
  const tag = element.tagName;
  const edit = buildAttributeInsertEdit(element.range.start, element.range.end, source, {
    tagName: tag,
    attrName: "aria-label",
    attrValue: icon.label,
    dialect: "jsx",
  });
  if (edit === null) return undefined;
  return {
    primary: {
      label: `add aria-label="${icon.label}" to <${tag}>`,
      edit,
    },
    alternatives: [],
  };
}
